-- ============================================================
-- Migration: admin block-plan registry
-- Creates subdivision_lots, the exact per-lot coordinates imported from the
-- City's block plans. Run once against the live database.
--
-- The app also creates this table automatically at boot via
-- src/db/ensureSubdivisionLots.js on both engines, so running this by hand is
-- only needed for a manual setup.
-- ============================================================

-- PostgreSQL (Supabase)
CREATE TABLE IF NOT EXISTS "subdivision_lots" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "subdivision_key" varchar(150) NOT NULL,
  "block" varchar(30) NOT NULL DEFAULT '',
  "lot" varchar(30) NOT NULL DEFAULT '',
  "latitude" double precision NOT NULL,
  "longitude" double precision NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  UNIQUE ("subdivision_key", "block", "lot")
);

